#!/usr/bin/env python3
"""P-code for the pi32 / q32s constructors generated by gen_jl.py, compiled from objdump's own syntax strings.

sem(form, ops, universe, G) -> (disassembly actions, p-code body) or None.

Behaviour comes from the syntax itself (it is C-like and explicit) plus the facts the CC0 pi32v2 table records for the same syntax
(flags, register-list order, saturation); for pi32 and q32s those carry-overs are ASSUMPTIONS (no vendor manual, no hardware tests):
they are listed in GHIDRA-RARE.md.  Forms whose behaviour is not known call a pcodeop named after the template.
"""
import re

USEROPS = set()
FALLBACK = []
WHY = {}
ARCH = None
GPR = SFR = []
CONDS = ['eq', 'ne', 'cs', 'cc', 'mi', 'pl', 'vs', 'vc', 'hi', 'ls', 'ge', 'lt', 'gt', 'le', 'al']
COND_EXPR = {
    'eq': '(psr & 4) != 0', 'ne': '(psr & 4) == 0', 'cs': '(psr & 2) != 0', 'cc': '(psr & 2) == 0',
    'mi': '(psr & 8) != 0', 'pl': '(psr & 8) == 0', 'vs': '(psr & 1) != 0', 'vc': '(psr & 1) == 0',
    'hi': '((psr & 2) != 0) && ((psr & 4) == 0)', 'ls': '((psr & 2) == 0) || ((psr & 4) != 0)',
    'ge': '(((psr >> 3) ^ psr) & 1) == 0', 'lt': '(((psr >> 3) ^ psr) & 1) != 0',
    'gt': '((psr & 4) == 0) && ((((psr >> 3) ^ psr) & 1) == 0)', 'le': '((psr & 4) != 0) || ((((psr >> 3) ^ psr) & 1) != 0)',
    'al': '1 == 1',
}
# which printed 'if (nzcv OP 0)' / 'ifs (...)' is which condition
PRINTED = {('ifs', '=='): 'eq', ('ifs', '!='): 'ne', ('if', '>='): 'cs', ('if', '<'): 'cc', ('if', '>'): 'hi', ('if', '<='): 'ls',
           ('ifs', '>='): 'ge', ('ifs', '<'): 'lt', ('ifs', '>'): 'gt', ('ifs', '<='): 'le'}
ALL = []
EXTRA_PATS = []
GEN = None

PRELUDE = '''
macro bitrev(dst, x) {
	local t:4 = x;
	t = ((t >> 1) & 0x55555555) | ((t & 0x55555555) << 1);
	t = ((t >> 2) & 0x33333333) | ((t & 0x33333333) << 2);
	t = ((t >> 4) & 0x0f0f0f0f) | ((t & 0x0f0f0f0f) << 4);
	t = ((t >> 8) & 0x00ff00ff) | ((t & 0x00ff00ff) << 8);
	dst = (t >> 16) | (t << 16);
}
macro setNZ(res) {
	psr = (psr & 0xfffffff3) | (zext(res == 0) << 2) | (zext(res s< 0) << 3);
}
macro setAdd(a, b, res) {
	psr = (psr & 0xfffffff0) | zext(((a ^ res) & (b ^ res)) s< 0) | (zext(res < a) << 1) | (zext(res == 0) << 2) | (zext(res s< 0) << 3);
}
macro setSub(a, b, res) {
	psr = (psr & 0xfffffff0) | zext(((a ^ b) & (a ^ res)) s< 0) | (zext(a >= b) << 1) | (zext(res == 0) << 2) | (zext(res s< 0) << 3);
}
define pcodeop Breakpoint;
define pcodeop HBreakpoint;
define pcodeop Idle;
define pcodeop CoreSynchronize;
define pcodeop SystemSynchronize;
define pcodeop SystemCall;
define pcodeop ClearLock;
define pcodeop SetLock;
define pcodeop SendEventLocal;
define pcodeop SendEventGlobal;
define pcodeop WaitForEvent;
define pcodeop Trigger;
define pcodeop SoftwareInterrupt;
define pcodeop Exception;
define pcodeop InterruptDisable;
define pcodeop InterruptEnable;
define pcodeop CacheFlush;
define pcodeop CacheFlushInvalidate;
define pcodeop CacheInvalidate;
define pcodeop Prefetch;
define pcodeop IllegalInstruction;
'''


def setup(arch, gpr, sfr):
    global ARCH, GPR, SFR
    ARCH, GPR, SFR = arch, gpr, sfr


class Unsupported(Exception):
    pass


class C:
    def __init__(self, form, ops, uni):
        self.form, self.ops, self.uni = form, ops, uni
        self.lines = []
        self.n = 0
        self.labels = 0

    def tmp(self):
        self.n += 1
        return 't%d' % self.n

    def label(self):
        self.labels += 1
        return 'L%d' % self.labels

    def emit(self, s):
        self.lines.append('\t' + s)

    def rd(self, x, size=4):
        if x.startswith('@'):
            o = self.ops[int(x[1:])]
            if o.kind in ('N',) and o.const is None and re.match(r'f\d+_', o.val or ''):
                return '(%s:4)' % o.val
            if o.const is not None and o.kind == 'N':
                return '%d' % (o.const & 0xffffffff)
            return o.val
        if re.fullmatch(r'-?\d+', x):
            v = int(x) & 0xffffffff
            return '0x%x' % v
        if x == 'pc':
            return 'inst_start'
        if x in GPR or x in SFR:
            return x
        raise Unsupported(x)

    def wr(self, x):
        if x.startswith('@'):
            o = self.ops[int(x[1:])]
            if o.reg is None:
                raise Unsupported('dest ' + x)
            return o.reg
        if x in GPR or x in SFR:
            return x
        raise Unsupported('dest ' + x)


ATOM = r'(@\d+|-?\d+|[a-z][a-z0-9_]*)'
SIGNS = {'(s)': 's', '(u)': 'u'}


def flagclass(tpl):
    if re.search(r'^\{R\} (\+=|-=|=) .*(\+|-)', tpl) and not re.search(r'\[|\*|<|>|&|\||\^|/|%', tpl):
        return 'NZCV'
    return ''


def alu(op, a, b, sign):
    if op == '+':
        return '%s + %s' % (a, b)
    if op == '-':
        return '%s - %s' % (a, b)
    if op == '*':
        return '%s * %s' % (a, b)
    if op == '/':
        return '%s %s %s' % (a, '/' if sign == 'u' else 's/', b)
    if op == '%':
        return '%s %s %s' % (a, '%' if sign == 'u' else 's%', b)
    if op in ('&', '|', '^'):
        return '%s %s %s' % (a, op, b)
    if op == '<<':
        return '%s << %s' % (a, b)
    if op == '>>':
        return '%s >> %s' % (a, b)
    if op == '>>>':
        return '%s s>> %s' % (a, b)
    raise Unsupported(op)


def shift_flags(c, op, a, b, res):
    """N Z follow the result; C is the last bit shifted out (kept for a zero count); V kept (pi32v2 table, assumed here)."""
    t = c.tmp()
    if op == '<<':
        c.emit('local %s:4 = 0;' % t)
        c.emit('if (%s == 0) goto <keep_%s>;' % (b, t))
        c.emit('%s = (%s >> (32 - %s)) & 1;' % (t, a, b))
        c.emit('psr = (psr & 0xfffffffd) | (%s << 1);' % t)
        c.emit('<keep_%s>' % t)
    else:
        sh = '>>' if op == '>>' else 's>>'
        c.emit('local %s:4 = 0;' % t)
        c.emit('if (%s == 0) goto <keep_%s>;' % (b, t))
        c.emit('%s = (%s %s (%s - 1)) & 1;' % (t, a, sh, b))
        c.emit('psr = (psr & 0xfffffffd) | (%s << 1);' % t)
        c.emit('<keep_%s>' % t)
    c.emit('setNZ(%s);' % res)


def cond_code(form):
    """Condition (0..14) of a 'nzcv ??' form: read from the bits that differ between the known conditions of its family."""
    fam = lambda f: (f['n'], re.sub(r'^ifs? ', 'if ', re.sub(r'\(nzcv [^)]*\)', '(nzcv X)', f['tpl'])))
    key = fam(form)
    known = {}
    for f in ALL:
        if f is not form and fam(f) == key:
            m = re.match(r'^(ifs?) \(nzcv (==|!=|>=|<=|>|<) \{N\}\)', f['tpl'])
            if m:
                known[PRINTED[(m.group(1), m.group(2))]] = f['val']
    if not known:
        return None
    vals = list(known.values())
    diff = 0
    for v in vals:
        diff |= v ^ vals[0]
    bits = [b for b in range(64) if (diff >> b) & 1]
    # the condition field is the set of bits that differ among known members (assume the four lowest-order differing bits form it)
    def code_of(v):
        return sum(((v >> b) & 1) << i for i, b in enumerate(bits))
    for cname, v in known.items():
        pass
    return code_of(form['val']), bits, known, code_of


def as4(x):
    return '%s:4' % x if re.fullmatch(r'(0x[0-9a-f]+|\d+)', x) else x


def sem(form, ops, uni, G):
    global GEN
    GEN = G
    tpl = form['tpl']
    c = C(form, ops, uni)
    try:
        r = compile_form(c, form)
    except Unsupported as ex:
        r = None
        WHY[tpl] = 'unsupported: %s' % ex
    if r is None:
        return fallback(c, form)
    return r


def fallback(c, form):
    tpl = form['tpl']
    FALLBACK.append(tpl)
    name = 'jl_' + re.sub(r'[^A-Za-z0-9]+', '_', re.sub(r'\{([RSNL])\}', lambda m: {'R': 'r', 'S': 's', 'N': 'n', 'L': 'l'}[m.group(1)], tpl)).strip('_')
    USEROPS.add(name)
    args = []
    first = None
    s = tpl
    lhs = re.match(r'^\{R\}(?=[ ,]*[^,]*=)', tpl)
    body = []
    dest = None
    for i, o in enumerate(c.ops):
        if o.kind in ('R', 'S') and o.reg is not None and i == 0 and re.match(r'^\{[RS]\} (<?[-+&|^*/%<>c]*=)', tpl):
            dest = o.reg
        else:
            if o.val is not None:
                a = c.rd('@%d' % i) if o.const is None or o.kind == 'N' else o.val
                if re.fullmatch(r'(0x[0-9a-f]+|\d+)', a):
                    a = '%s:4' % a
                args.append(a)
    call = '%s(%s)' % (name, ', '.join(args))
    if dest:
        return '', '\t%s = %s;\n' % (dest, call)
    return '', '\t%s;\n' % call


def compile_form(c, form):
    tpl = form['tpl']
    ops = c.ops
    # substitute constants, number the variable operands
    toks = re.split(r'(\{[RSNL]\})', tpl)
    k = 0
    parts = []
    for p in toks:
        if re.fullmatch(r'\{[RSNL]\}', p):
            o = ops[k]
            if o.const is not None and o.kind in ('R', 'S'):
                parts.append(GPR[o.const] if o.kind == 'R' else SFR[o.const])
            elif o.const is not None and o.kind == 'N':
                parts.append(str(o.const))
            else:
                parts.append('@%d' % k)
            k += 1
        else:
            parts.append(p)
    s = ''.join(parts).strip()
    sign = None
    m = re.search(r' \((s|u|sat|brev)\)$', s)
    q = None
    if m:
        q = m.group(1)
        s = s[:m.start()]
        if q in ('s', 'u'):
            sign = q
    fc = flagclass(tpl)

    # ---- no-operand
    simple = {
        'nop': '', 'bkpt': 'Breakpoint();', 'hbkpt': 'HBreakpoint();', 'csync': 'CoreSynchronize();', 'ssync': 'SystemSynchronize();',
        'illeg': 'IllegalInstruction();', 'wfe': 'WaitForEvent();', 'lockset': 'SetLock();', 'lockclr': 'ClearLock();',
        'sevl': 'SendEventLocal();', 'sevg': 'SendEventGlobal();', 'idle': 'Idle();', 'syscall': 'SystemCall();', 'trigger': 'Trigger();',
        'cli': 'InterruptDisable();', 'sti': 'InterruptEnable();',
        'rts': 'return [rets];', 'rti': 'return [reti];', 'rte': 'return [rete];', 'rtx': 'return [retx];',
    }
    if s in simple:
        return '', ('\t%s\n' % simple[s]) if simple[s] else ''
    m = re.fullmatch(r'(cli|sti) ' + ATOM, s)
    if m:
        return '', '\t%s();\n' % ('InterruptDisable' if m.group(1) == 'cli' else 'InterruptEnable')
    m = re.fullmatch(r'(swi|excpt) ' + ATOM, s)
    if m:
        return '', '\t%s(%s);\n' % ('SoftwareInterrupt' if m.group(1) == 'swi' else 'Exception', c.rd(m.group(2)))
    m = re.fullmatch(r'(flush|flushinv|iflush|pfetch) \[(.*)\]', s)
    if m:
        a, pre, post = mem_addr(c, m.group(2).replace(' ', ''))
        nm = {'flush': 'CacheFlush', 'flushinv': 'CacheFlushInvalidate', 'iflush': 'CacheInvalidate', 'pfetch': 'Prefetch'}[m.group(1)]
        return '', ''.join(pre) + '\t%s(%s);\n' % (nm, a) + ''.join(post)
    m = re.fullmatch(ATOM + r' = addr\((@\d+)\)', s)
    if m:
        c.emit('%s = %s;' % (c.wr(m.group(1)), c.rd(m.group(2))))
        return '', body(c)
    m = re.fullmatch(r'(tbb|tbh) \[(.*)\]', s)
    if m:
        ea, pre, post = mem_addr(c, m.group(2).replace(' ', ''))
        c.emit('local idx:4 = %s;' % ea)
        if m.group(1) == 'tbb':
            c.emit('local e:1 = *:1 (inst_next + idx);')
        else:
            c.emit('local e:2 = *:2 (inst_next + (idx & 0xfffffffe));')
        c.emit('local d:4 = inst_next + (zext(e) << 1);')
        c.emit('goto [d];')
        return '', body(c)
    m = re.fullmatch(r'testset b\[(.*)\]', s)
    if m:
        ea, pre, post = mem_addr(c, m.group(1).replace(' ', ''))
        c.emit('local ta:4 = %s;' % ea)
        c.emit('local ov:1 = *:1 ta;')
        c.emit('psr = (psr & 0xfffffff0) | (zext(ov) & 0xf);')
        c.emit('*:1 ta = 0xff;')
        return '', body(c)
    m = re.fullmatch(r'\[--sp\] = ' + ATOM, s)
    if m:
        c.emit('sp = sp - 4;')
        c.emit('*:4 sp = %s;' % c.rd(m.group(1)))
        return '', body(c)
    m = re.fullmatch(r'pc = \[sp\+\+\]', s)
    if m:
        c.emit('local np:4 = *:4 sp;')
        c.emit('sp = sp + 4;')
        c.emit('return [np];')
        return '', body(c)
    m = re.fullmatch(ATOM + r' (\+=|-=) ' + ATOM + r' \* ' + ATOM, s)
    if m and m.group(1) != 'macc':
        d = c.wr(m.group(1))
        c.emit('%s = %s %s (%s * %s);' % (d, d, m.group(2)[0], c.rd(m.group(3)), c.rd(m.group(4))))
        return '', body(c)
    m = re.fullmatch(ATOM + r' = (rev|revs)(@\d+|\d*)\(' + ATOM + r'(?:\.l)?\)', s)
    if m:
        kind, nn, src = m.group(2), m.group(3), m.group(4)
        d = c.wr(m.group(1))
        c.emit('local a:4 = %s;' % c.rd(src))
        if kind == 'rev':
            if nn.startswith('@'):
                c.emit('local nn:4 = %s;' % c.rd(nn))
            else:
                c.emit('local nn:4 = %s;' % (nn or '8'))
            c.emit('local r:4 = ((a & 0xff) << 24) | ((a & 0xff00) << 8) | ((a >> 8) & 0xff00) | (a >> 24);')
            c.emit('if (nn != 16) goto <done>;')
            c.emit('r = ((a & 0x00ff00ff) << 8) | ((a >> 8) & 0x00ff00ff);')
            c.emit('<done>')
            c.emit('%s = r;' % d)
        else:
            c.emit('local h:2 = a:2;')
            c.emit('local sw:2 = (h << 8) | (h >> 8);')
            c.emit('%s = sext(sw);' % d)
        return '', body(c)
    m = re.fullmatch(r'cc = ' + ATOM, s)
    if m:
        c.emit('psr = (psr & 0xfffffffd) | (zext(%s != 0) << 1);' % c.rd(m.group(1)))
        return '', body(c)
    # ---- special: macc / blocks are handled by the arch module
    r = special(c, form, s, sign, q)
    if r is not None:
        return r
    # ---- blocks (pi32)
    r = blocks(c, form, s)
    if r is not None:
        return r
    # ---- branches
    r = branch(c, form, s)
    if r is not None:
        return r
    # ---- register lists
    r = lists(c, form, s)
    if r is not None:
        return r
    # ---- memory
    r = memory(c, form, s, sign)
    if r is not None:
        return r
    # ---- data processing
    r = data(c, form, s, sign, q, fc)
    if r is not None:
        return r
    return None


def body(c):
    return '\n'.join(c.lines) + '\n'


def mem_addr(c, a):
    """address text without spaces -> (address expression, pre lines, post lines)."""
    pre, post = [], []
    m = re.fullmatch(r'addr\((@\d+)\)', a)
    if m:
        return c.rd(m.group(1)), pre, post
    m = re.fullmatch(ATOM + r'\+\+=' + ATOM, a)
    if m:
        b = c.wr(m.group(1)) if m.group(1).startswith('@') or m.group(1) in GPR else None
        post.append('\t%s = %s + %s;\n' % (b, b, c.rd(m.group(2))))
        t = c.tmp()
        pre.append('\tlocal %s:4 = %s;\n' % (t, c.rd(m.group(1))))
        return t, pre, post
    m = re.fullmatch(r'\+\+' + ATOM + '=' + ATOM, a)
    if m:
        b = c.wr(m.group(1))
        pre.append('\t%s = %s + %s;\n' % (b, b, c.rd(m.group(2))))
        return c.rd(m.group(1)), pre, post
    m = re.fullmatch(ATOM + r'\+' + ATOM + r'<<(\d+)', a)
    if m:
        return '(%s + (%s << %s))' % (c.rd(m.group(1)), c.rd(m.group(2)), m.group(3)), pre, post
    m = re.fullmatch(ATOM + r'\+' + ATOM, a)
    if m:
        return '(%s + %s)' % (c.rd(m.group(1)), c.rd(m.group(2))), pre, post
    m = re.fullmatch(ATOM, a)
    if m:
        return c.rd(m.group(1)), pre, post
    raise Unsupported('address ' + a)


SZ = {'': 4, 'b': 1, 'h': 2, 'd': 8}


def memory(c, form, s, sign):
    # load
    m = re.fullmatch(ATOM + r' = ([bhd]?)\[(.*)\]', s)
    if m and not m.group(1).startswith('-'):
        dest, sz, a = m.group(1), SZ[m.group(2)], m.group(3).replace(' ', '')
        if sz == 8:
            raise Unsupported('d')
        ea, pre, post = mem_addr(c, a)
        d = c.wr(dest)
        for l in pre:
            c.lines.append(l.rstrip('\n'))
        c.emit('local v:%d = *:%d (%s);' % (sz, sz, ea))
        for l in post:
            c.lines.append(l.rstrip('\n'))
        if sz == 4:
            c.emit('%s = v;' % d)
        else:
            ext = 'sext' if sign == 's' else 'zext'
            c.emit('%s = %s(v);' % (d, ext))
        return '', body(c)
    m = re.fullmatch(ATOM + r', ' + ATOM + r' = d\[(.*)\]', s)
    if m:
        a = m.group(3).replace(' ', '')
        ea, pre, post = mem_addr(c, a)
        for l in pre:
            c.lines.append(l.rstrip('\n'))
        c.emit('local v0:4 = *:4 (%s);' % ea)
        c.emit('local v1:4 = *:4 (%s + 4);' % ea)
        for l in post:
            c.lines.append(l.rstrip('\n'))
        c.emit('%s = v0;' % c.wr(m.group(1)))
        c.emit('%s = v1;' % c.wr(m.group(2)))
        return '', body(c)
    # store
    m = re.fullmatch(r'([bhd]?)\[(.*)\] = ' + ATOM, s)
    if m:
        sz, a, src = SZ[m.group(1)], m.group(2).replace(' ', ''), m.group(3)
        ea, pre, post = mem_addr(c, a)
        for l in pre:
            c.lines.append(l.rstrip('\n'))
        v = c.rd(src)
        if sz == 4:
            c.emit('*:4 (%s) = %s;' % (ea, v))
        else:
            c.emit('*:%d (%s) = %s:%d;' % (sz, ea, v, sz))
        for l in post:
            c.lines.append(l.rstrip('\n'))
        return '', body(c)
    m = re.fullmatch(r'd\[(.*)\] = ' + ATOM + r', ' + ATOM, s)
    if m:
        ea, pre, post = mem_addr(c, m.group(1).replace(' ', ''))
        for l in pre:
            c.lines.append(l.rstrip('\n'))
        c.emit('local s0:4 = %s;' % c.rd(m.group(2)))
        c.emit('local s1:4 = %s;' % c.rd(m.group(3)))
        c.emit('*:4 (%s) = s0;' % ea)
        c.emit('*:4 (%s + 4) = s1;' % ea)
        for l in post:
            c.lines.append(l.rstrip('\n'))
        return '', body(c)
    # read-modify-write
    m = re.fullmatch(r'\[(.*)\] (\|=|&=|\^=) (\(~)?' + ATOM + r'\)?', s)
    if m:
        ea, pre, post = mem_addr(c, m.group(1).replace(' ', ''))
        v = c.rd(m.group(4))
        if m.group(3):
            v = '(~%s)' % v
        op = m.group(2)[0]
        c.emit('local mv:4 = *:4 (%s);' % ea)
        c.emit('mv = mv %s %s;' % (op, v))
        c.emit('*:4 (%s) = mv;' % ea)
        c.emit('setNZ(mv);')
        return '', body(c)
    m = re.fullmatch(r'\[(.*)\] = ' + ATOM, s)
    return None


def lists(c, form, s):
    m = re.fullmatch(r'(@\d+) = \[(.*)\]', s)
    mm = re.fullmatch(r'\[(.*)\] = (@\d+)', s)
    load = True
    if m and c.ops[int(m.group(1)[1:])].kind == 'L':
        lst, a = m.group(1), m.group(2)
    elif mm and c.ops[int(mm.group(2)[1:])].kind == 'L':
        lst, a, load = mm.group(2), mm.group(1), False
    else:
        return None
    mo = re.fullmatch(r'(--|-|\+\+|\+)?(@\d+|sp|r\d+)(--|\+\+|\+)?', a.replace(' ', ''))
    if not mo:
        raise Unsupported('list address ' + a)
    pre, base, post = mo.group(1), mo.group(2), mo.group(3)
    uni = c.uni
    rn = lambda nm: 'sp' if (ARCH == 'pi32' and nm == 'r15') else nm
    mask = c.rd(lst)
    # addresses ascend with the register order; lowest numbered register at the lowest address
    order = sorted(uni, key=lambda nm: reg_rank(nm))
    c.emit('local m:4 = %s;' % mask)
    c.emit('local cnt:4 = 0;')
    for nm in order:
        c.emit('cnt = cnt + ((m >> %d) & 1);' % uni.index(nm))
    c.emit('local ea:4 = %s;' % c.rd(base))
    down = pre in ('--', '-')
    if down:
        c.emit('ea = ea - (cnt * 4);')
    if down and pre == '--':
        c.emit('%s = ea;' % c.wr(base))
    c.emit('local p:4 = ea;')
    pc_pop = False
    for nm in order:
        i = uni.index(nm)
        lab = c.label()
        c.emit('if (((m >> %d) & 1) == 0) goto <%s>;' % (i, lab))
        if load:
            if nm == 'pc':
                c.emit('local newpc:4 = *:4 p;')
                pc_pop = True
            else:
                c.emit('%s = *:4 p;' % rn(nm))
        else:
            c.emit('*:4 p = %s;' % ('inst_start' if nm == 'pc' else rn(nm)))
        c.emit('p = p + 4;')
        c.emit('<%s>' % lab)
    if post in ('++',):
        c.emit('%s = ea + (cnt * 4);' % c.wr(base))
    if pc_pop:
        c.emit('if (((m >> %d) & 1) == 0) goto <nopc>;' % uni.index('pc'))
        c.emit('%s [newpc];' % ('return' if base == 'sp' else 'goto'))
        c.emit('<nopc>')
    return '', body(c)


def reg_rank(nm):
    m = re.fullmatch(r'r(\d+)', nm)
    if m:
        return int(m.group(1))
    if nm == 'sp':
        return 15
    if nm in SFR:
        return 100 + SFR.index(nm)
    return 200


def lin_expr(c, k):
    """Disassembly-time expression of a linear operand (for context actions), adding its fields to the pattern."""
    import gen_jl
    tok = c.form['tokens'][k]
    fit = tok['fit']
    if fit['type'] == 'const':
        return str(fit['val'])
    if fit['type'] != 'lin':
        raise Unsupported('operand %d is not linear' % k)
    terms, c0 = gen_jl.lin_terms(c.form['n'], fit)
    for f, _ in terms:
        EXTRA_PATS.append(f)
    return '(%s)' % gen_jl.expr_of(terms, c0)


def blocks(c, form, s):
    n = form['n']
    m = re.fullmatch(r'(ifs?) \(nzcv (==|!=|>=|<=|>|<|\?\?) ' + ATOM + r'\) \{', s)
    if m:
        cond = nzcv_cond(c, form, m.group(1), m.group(2))
        a = GEN.fld(n, 2, 3, 'u')
        b = GEN.fld(n, 0, 1, 'u')
        EXTRA_PATS.extend([a, b])
        act = ('ifblock = 1; thenbranch = %s + 1; elsebranch = %s; closebracket = 0; globalset(inst_next, ifblock); '
               'globalset(inst_next, thenbranch); globalset(inst_next, elsebranch); globalset(inst_next, closebracket);') % (a, b)
        c.emit('cres = 0;')
        if cond == 'al':
            c.emit('cres = 1;')
        else:
            c.emit('if (!(%s)) goto <no>;' % COND_EXPR[cond])
            c.emit('cres = 1;')
            c.emit('<no>')
        return act, body(c)
    m = re.fullmatch(r'rep (@\d+|\d+), (@\d+|\d+) \{', s)
    if m:
        # the body is the next N instructions; the counter is a register or a number
        nt = [i for i, t in enumerate(form['tokens']) if t['kind'] == 'N']
        ntok = 0
        tokidx = {}
        # token indices: first operand = body length (an N token), second = count (R or N)
        toks = form['tokens']
        len_k = 0
        cnt_k = 1
        cnt = c.rd(m.group(2))
        act = 'repcount = %s; globalset(inst_next, repcount);' % lin_expr(c, len_k)
        c.emit('rep_count = %s;' % (cnt if m.group(2).startswith('@') or True else cnt))
        c.emit('rep_start = inst_next;')
        return act, body(c)
    return None


def branch(c, form, s):
    ops = c.ops
    def T(x):
        o = ops[int(x[1:])]
        return o.val if o.is_target else '[%s]' % c.rd(x)
    m = re.fullmatch(r'(goto|call) ' + ATOM, s)
    if m:
        if m.group(1) == 'call':
            c.emit('rets = inst_next;')
        dest = T(m.group(2)) if m.group(2).startswith('@') else None
        if dest is None:
            raise Unsupported('goto')
        c.emit('%s %s;' % (m.group(1), dest))
        return '', body(c)
    # condition-code gotos and blocks
    m = re.fullmatch(r'(ifs?) \(nzcv (==|!=|>=|<=|>|<|\?\?) ' + ATOM + r'\) goto ' + ATOM, s)
    if m:
        cond = nzcv_cond(c, form, m.group(1), m.group(2))
        d = T(m.group(4))
        if cond == 'al':
            c.emit('goto %s;' % d)
            return '', body(c)
        c.emit('if (!(%s)) goto <skip>;' % COND_EXPR[cond])
        c.emit('goto %s;' % d)
        c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'if(eq|ne|cs|cc|mi|pl|vs|vc|hi|ls|ge|lt|gt|le|al) goto ' + ATOM, s)
    if m:
        if m.group(1) != 'al':
            c.emit('if (!(%s)) goto <skip>;' % COND_EXPR[m.group(1)])
        c.emit('goto %s;' % T(m.group(2)))
        if m.group(1) != 'al':
            c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'(ifs?) \(' + ATOM + r' (==|!=|<=|>=|<|>) ' + ATOM + r'\) goto ' + ATOM, s)
    if m:
        sg = m.group(1) == 'ifs'
        op = m.group(3)
        a, b = c.rd(m.group(2)), c.rd(m.group(4))
        cmpop = {'==': '==', '!=': '!=', '<': 's<' if sg else '<', '<=': 's<=' if sg else '<=', '>': 's>' if sg else '>', '>=': 's>=' if sg else '>='}[op]
        c.emit('if (!(%s %s %s)) goto <skip>;' % (a, cmpop, b))
        c.emit('goto %s;' % T(m.group(5)))
        c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'if \(' + ATOM + r' (==|!=) ' + ATOM + r'\) goto ' + ATOM, s)
    if m:
        c.emit('if (!(%s %s %s)) goto <skip>;' % (c.rd(m.group(1)), m.group(2), c.rd(m.group(3))))
        c.emit('goto %s;' % T(m.group(4)))
        c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'ifs? \(\(' + ATOM + r' & ' + ATOM + r'\) (==|!=) ' + ATOM + r'\) goto ' + ATOM, s)
    if m:
        c.emit('if (!(((%s & %s) %s %s))) goto <skip>;' % (c.rd(m.group(1)), c.rd(m.group(2)), m.group(3), c.rd(m.group(4))))
        c.emit('goto %s;' % T(m.group(5)))
        c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'if \(--' + ATOM + r' != ' + ATOM + r'\) goto ' + ATOM, s)
    if m:
        r = c.wr(m.group(1))
        c.emit('%s = %s - 1;' % (r, r))
        c.emit('if (%s == %s) goto <skip>;' % (r, c.rd(m.group(2))))
        c.emit('goto %s;' % T(m.group(3)))
        c.emit('<skip>')
        return '', body(c)
    m = re.fullmatch(r'(ifs?) \(nzcv (==|!=|>=|<=|>|<|\?\?) ' + ATOM + r'\) goto ' + ATOM, s)
    return None


def nzcv_cond(c, form, ifs, op):
    if op != '??':
        return PRINTED[(ifs, op)]
    r = cond_code(form)
    if r is None:
        raise Unsupported('condition ??')
    code, bits, known, code_of = r
    if not 0 <= code <= 14:
        raise Unsupported('condition code %d' % code)
    for cname, v in known.items():
        if code_of(v) != CONDS.index(cname):
            raise Unsupported('condition field does not fit the known conditions')
    return CONDS[code]


def special(c, form, s, sign, q):
    ops = c.ops
    # macc (pi32)
    if 'macc' not in s:
        return None
    m = re.fullmatch(r'macc (=|\+=|-=) ' + ATOM + r' \* ' + ATOM, s)
    if m:
        a, b = c.rd(m.group(2)), c.rd(m.group(3))
        ext = 'sext' if sign == 's' else 'zext'
        c.emit('local pr:8 = %s(%s) * %s(%s);' % (ext, a, ext, b))
        c.emit('macc = %s;' % {'=': 'pr', '+=': 'macc + pr', '-=': 'macc - pr'}[m.group(1)])
        return '', body(c)
    m = re.fullmatch(r'macc (=|\+=|-=) (h?)\[(.*)\] \* \[(.*)\]', s)
    if m:
        ext = 'sext' if sign == 's' else 'zext'
        e1, pre1, post1 = mem_addr(c, m.group(3).replace(' ', ''))
        e2, pre2, post2 = mem_addr(c, m.group(4).replace(' ', ''))
        for l in pre1 + pre2:
            c.lines.append(l.rstrip('\n'))
        if m.group(2) == 'h':
            c.emit('local a1:2 = *:2 (%s);' % e1)
        else:
            c.emit('local a1:4 = *:4 (%s);' % e1)
        c.emit('local a2:4 = *:4 (%s);' % e2)
        c.emit('local pr:8 = %s(a1) * %s(a2);' % (ext, ext))
        c.emit('macc = %s;' % {'=': 'pr', '+=': 'macc + pr', '-=': 'macc - pr'}[m.group(1)])
        for l in post1 + post2:
            c.lines.append(l.rstrip('\n'))
        return '', body(c)
    m = re.fullmatch(r'macc = ' + ATOM, s)
    if m:
        c.emit('macc = zext(%s);' % as4(c.rd(m.group(1))))
        return '', body(c)
    m = re.fullmatch(r'macc (<<=|>>=|>>>=) ' + ATOM, s)
    if m:
        n = c.rd(m.group(2))
        if re.fullmatch(r'0x[0-9a-f]+', n) and int(n, 16) == 0:
            n = '64'
        if m.group(2).startswith('@') and ops[int(m.group(2)[1:])].kind == 'N':
            nn = '(%s)' % n
            c.emit('local sh:4 = %s;' % nn)
            c.emit('if (sh != 0) goto <go>;')
            c.emit('sh = 64;')
            c.emit('<go>')
            n = 'sh'
        op = {'<<=': '<<', '>>=': '>>', '>>>=': 's>>'}[m.group(1)]
        c.emit('macc = macc %s %s;' % (op, n))
        return '', body(c)
    m = re.fullmatch(r'(@\d+) = macc (>>>?) ' + ATOM, s)
    if m:
        op = '>>' if m.group(2) == '>>' else 's>>'
        c.emit('local sh:4 = %s;' % c.rd(m.group(3)))
        c.emit('local mv:8 = macc %s sh;' % op)
        c.emit('%s = mv:4;' % c.wr(m.group(1)))
        return '', body(c)
    return None


def data(c, form, s, sign, q, fc):
    ops = c.ops
    # moves
    m = re.fullmatch(ATOM + r' = ' + ATOM, s)
    if m:
        dst, src = m.group(1), m.group(2)
        if dst == 'pc':
            c.emit('goto [%s];' % c.rd(src))
            return '', body(c)
        c.emit('%s = %s;' % (c.wr(dst), c.rd(src)))
        return '', body(c)
    # half moves  R.h = N / R.l = N
    m = re.fullmatch(ATOM + r'\.(h|l) = ' + ATOM, s)
    if m:
        d = c.wr(m.group(1))
        v = c.rd(m.group(3))
        if m.group(2) == 'h':
            c.emit('%s = (%s & 0xffff) | ((%s & 0xffff) << 16);' % (d, d, v))
        else:
            c.emit('%s = (%s & 0xffff0000) | (%s & 0xffff);' % (d, d, v))
        return '', body(c)
    # compare / test
    m = re.fullmatch(r'(cmp|cmn|tst) ' + ATOM + r', ' + ATOM, s)
    if m:
        a, b = c.rd(m.group(2)), c.rd(m.group(3))
        c.emit('local a:4 = %s;' % a)
        c.emit('local b:4 = %s;' % b)
        if m.group(1) == 'cmp':
            c.emit('local r:4 = a - b;')
            c.emit('setSub(a, b, r);')
        elif m.group(1) == 'cmn':
            c.emit('local r:4 = a + b;')
            c.emit('setAdd(a, b, r);')
        else:
            c.emit('local r:4 = a & b;')
            c.emit('setNZ(r);')
        return '', body(c)
    # unary
    m = re.fullmatch(ATOM + r' = (-|~)' + ATOM + r'', s)
    if m:
        d = c.wr(m.group(1))
        if m.group(2) == '-':
            c.emit('local a:4 = %s;' % c.rd(m.group(3)))
            if q == 'sat':
                c.emit('local r:4 = 0 - a;')
                c.emit('if (a != 0x80000000) goto <ok>;')
                c.emit('r = 0x7fffffff;')
                c.emit('<ok>')
            else:
                c.emit('local r:4 = 0 - a;')
            c.emit('%s = r;' % d)
            c.emit('setSub(0, a, r);' if q != 'sat' else 'setNZ(r);')
        else:
            c.emit('local r:4 = ~%s;' % c.rd(m.group(3)))
            c.emit('%s = r;' % d)
            c.emit('setNZ(r);')
        return '', body(c)
    # extension
    m = re.fullmatch(ATOM + r' = ' + ATOM + r'\.(b|l)(\d?)', s)
    if m:
        v = c.rd(m.group(2))
        ext = 'sext' if sign == 's' or (sign is None and q == 's') else 'zext'
        which = m.group(3)
        if m.group(3) == 'b':
            sh = int(m.group(4) or 0) * 8
            c.emit('local sv:4 = %s >> %d;' % (v, sh))
            c.emit('local r:4 = %s(sv:1);' % ext)
        else:
            c.emit('local sv:4 = %s;' % v)
            c.emit('local r:4 = %s(sv:2);' % ext)
        c.emit('%s = r;' % c.wr(m.group(1)))
        c.emit('setNZ(r);')
        return '', body(c)
    # bit field ops
    m = re.fullmatch(ATOM + r' = (uextra|sextra)\(' + ATOM + r', p:(.+), l:(.+)\)', s)
    if m:
        def fieldval(t):
            mm = re.fullmatch(ATOM + r'\[(\d+):(\d+)\]', t)
            if mm:
                hi, lo = int(mm.group(2)), int(mm.group(3))
                return '((%s >> %d) & %d)' % (c.rd(mm.group(1)), lo, (1 << (hi - lo + 1)) - 1)
            return c.rd(t)
        c.emit('local p:4 = %s;' % fieldval(m.group(4)))
        c.emit('local l:4 = %s;' % fieldval(m.group(5)))
        c.emit('local v:4 = %s;' % c.rd(m.group(3)))
        c.emit('local r:4 = (v >> p) & ((1 << l) - 1);')
        if m.group(2) == 'sextra':
            c.emit('if (l == 0) goto <z>;')
            c.emit('if (((r >> (l - 1)) & 1) == 0) goto <z>;')
            c.emit('r = r | (0xffffffff << l);')
            c.emit('<z>')
        c.emit('%s = r;' % c.wr(m.group(1)))
        return '', body(c)
    m = re.fullmatch(ATOM + r' <= insert\(' + ATOM + r', p:(.+), l:(.+)\)', s)
    if m:
        def fieldval(t):
            mm = re.fullmatch(ATOM + r'\[(\d+):(\d+)\]', t)
            if mm:
                hi, lo = int(mm.group(2)), int(mm.group(3))
                return '((%s >> %d) & %d)' % (c.rd(mm.group(1)), lo, (1 << (hi - lo + 1)) - 1)
            return c.rd(t)
        c.emit('local p:4 = %s;' % fieldval(m.group(3)))
        c.emit('local l:4 = %s;' % fieldval(m.group(4)))
        c.emit('local mk:4 = ((1 << l) - 1) << p;')
        d = c.wr(m.group(1))
        c.emit('%s = (%s & ~mk) | ((%s << p) & mk);' % (d, d, c.rd(m.group(2))))
        return '', body(c)
    # clz / cls / rev / zcmp
    m = re.fullmatch(ATOM + r' = (clz|cls|zcmp|rev8|revs)\(' + ATOM + r'\)', s)
    if m:
        v = c.rd(m.group(3))
        d = c.wr(m.group(1))
        f = m.group(2)
        if f == 'clz':
            c.emit('%s = lzcount(%s);' % (d, v))
        elif f == 'cls':
            c.emit('local a:4 = %s;' % v)
            c.emit('if ((a s< 0)) goto <neg>;')
            c.emit('%s = lzcount(a);' % d)
            c.emit('goto <done>;')
            c.emit('<neg>')
            c.emit('%s = lzcount(~a);' % d)
            c.emit('<done>')
        elif f == 'zcmp':
            c.emit('local a:4 = %s;' % v)
            c.emit('%s = zext(a s> 0) - zext(a s< 0);' % d)
        elif f == 'rev8':
            c.emit('local a:4 = %s;' % v)
            c.emit('%s = ((a & 0xff) << 24) | ((a & 0xff00) << 8) | ((a >> 8) & 0xff00) | (a >> 24);' % d)
        return '', body(c)
    m = re.fullmatch(ATOM + r' = (rev|revs)(\d+)\(' + ATOM + r'\)', s)
    if m:
        raise Unsupported('rev%s' % m.group(3))
    # arithmetic
    carry = re.fullmatch(ATOM + r' = ' + ATOM + r' (\+|-) ' + ATOM + r' (\+ c|- !c)', s)
    if carry:
        d = c.wr(carry.group(1))
        c.emit('local a:4 = %s;' % c.rd(carry.group(2)))
        c.emit('local b:4 = %s;' % c.rd(carry.group(4)))
        c.emit('local cin:4 = (psr >> 1) & 1;')
        if carry.group(3) == '+':
            c.emit('local w:8 = zext(a) + zext(b) + zext(cin);')
            c.emit('local r:4 = w:4;')
            c.emit('%s = r;' % d)
            c.emit('psr = (psr & 0xfffffff0) | zext(((a ^ r) & (b ^ r)) s< 0) | (zext((w >> 32) != 0) << 1) | (zext(r == 0) << 2) | (zext(r s< 0) << 3);')
        else:
            c.emit('local w:8 = zext(a) - zext(b) - zext(1 - cin);')
            c.emit('local r:4 = w:4;')
            c.emit('%s = r;' % d)
            c.emit('psr = (psr & 0xfffffff0) | zext(((a ^ b) & (a ^ r)) s< 0) | (zext((w >> 32) == 0) << 1) | (zext(r == 0) << 2) | (zext(r s< 0) << 3);')
        return '', body(c)
    m = re.fullmatch(ATOM + r' (\+=|-=) ' + ATOM + r' (\+ c|\+ !c|- !c)', s)
    if m:
        return carry_compile(c, m.group(1), m.group(1), m.group(2)[0], m.group(3), m.group(4))
    # three operand
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' (\+|-|\*|/|%|&|\||\^|<<<|<<|>>>|>>|<>|<c>) ' + ATOM, s)
    if m:
        return binop(c, form, m.group(1), m.group(2), m.group(3), m.group(4), sign, fc)
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' & (?:~|\(~)' + ATOM + r'\)?', s)
    if m:
        d = c.wr(m.group(1))
        c.emit('local r:4 = %s & ~%s;' % (c.rd(m.group(2)), c.rd(m.group(3))))
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
        return '', body(c)
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' (&|\||\^) (~?)setbit\(' + ATOM + r'\)', s)
    if m:
        d = c.wr(m.group(1))
        bit = '(1 << (%s & 31))' % c.rd(m.group(5))
        if m.group(4):
            bit = '(~%s)' % bit
        c.emit('local r:4 = %s %s %s;' % (c.rd(m.group(2)), m.group(3), bit))
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
        return '', body(c)
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' & \(~' + ATOM + r'\)', s)
    if m:
        d = c.wr(m.group(1))
        c.emit('local r:4 = %s & ~%s;' % (c.rd(m.group(2)), c.rd(m.group(3))))
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
        return '', body(c)
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' - ' + ATOM, s)
    # two operand
    m = re.fullmatch(ATOM + r' (\+=|-=|\*=|&=|\|=|\^=|<<=|>>=|>>>=|<<<=|<>=|<c>=|/=|%=) (?:\(~)?' + ATOM + r'\)?(?: \(brev\))?', s)
    if m:
        neg = '(~' in s
        src = c.rd(m.group(3))
        if neg:
            src = '(~%s)' % src
        op = m.group(2)[:-1]
        return binop(c, form, m.group(1), m.group(1), op, m.group(3), sign, fc, srcexpr=src, brev=q == 'brev')
    m = re.fullmatch(ATOM + r' = ' + ATOM + r' - ' + ATOM, s)
    return None


def carry_compile(c, dst, a, op, b, kind):
    d = c.wr(dst)
    c.emit('local a:4 = %s;' % c.rd(a))
    c.emit('local b:4 = %s;' % c.rd(b))
    c.emit('local cin:4 = (psr >> 1) & 1;')
    if op == '+':
        c.emit('local w:8 = zext(a) + zext(b) + zext(cin);')
        c.emit('local r:4 = w:4;')
        c.emit('%s = r;' % d)
        c.emit('psr = (psr & 0xfffffff0) | zext(((a ^ r) & (b ^ r)) s< 0) | (zext((w >> 32) != 0) << 1) | (zext(r == 0) << 2) | (zext(r s< 0) << 3);')
    else:
        c.emit('local w:8 = zext(a) - zext(b) - zext(1 - cin);')
        c.emit('local r:4 = w:4;')
        c.emit('%s = r;' % d)
        c.emit('psr = (psr & 0xfffffff0) | zext(((a ^ b) & (a ^ r)) s< 0) | (zext((w >> 32) == 0) << 1) | (zext(r == 0) << 2) | (zext(r s< 0) << 3);')
    return '', body(c)


def binop(c, form, dst, a, op, b, sign, fc, srcexpr=None, brev=False):
    # note: for the three-operand form the arguments are (dst, a, op, b); for the two-operand form (dst, dst, op, b)
    if not re.fullmatch(r'\+|-|\*|/|%|&|\||\^|<<<|<<|>>>|>>|<>|<c>', op):
        # called as (dst, dst, 'op', b) from the two-operand rule
        pass
    d = c.wr(dst)
    av = c.rd(a)
    bv = srcexpr if srcexpr is not None else c.rd(b)
    c.emit('local a:4 = %s;' % av)
    c.emit('local b:4 = %s;' % bv)
    if brev:
        c.emit('local ra:4 = 0;')
        c.emit('local rb:4 = 0;')
        c.emit('bitrev(ra, a);')
        c.emit('bitrev(rb, b);')
        c.emit('local rr:4 = ra + rb;')
        c.emit('local r:4 = 0;')
        c.emit('bitrev(r, rr);')
        c.emit('%s = r;' % d)
        c.emit('psr = (psr & 0xfffffff0) | zext(((ra ^ rr) & (rb ^ rr)) s< 0) | (zext(rr < ra) << 1) | (zext(r == 0) << 2) | (zext(r s< 0) << 3);')
        return '', body(c)
    if op in ('+', '-'):
        c.emit('local r:4 = a %s b;' % op)
        c.emit('%s = r;' % d)
        c.emit('setAdd(a, b, r);' if op == '+' else 'setSub(a, b, r);')
    elif op in ('&', '|', '^', '*'):
        c.emit('local r:4 = a %s b;' % op)
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
    elif op in ('/', '%'):
        c.emit('local r:4 = 0;')
        c.emit('if (b == 0) goto <done>;')
        c.emit('r = a %s b;' % (('s' + op) if sign == 's' else op))
        c.emit('<done>')
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
    elif op in ('<<', '>>', '>>>'):
        c.emit('local r:4 = %s;' % alu(op, 'a', 'b', sign))
        c.emit('%s = r;' % d)
        shift_flags(c, op, 'a', 'b', 'r')
    elif op == '<>':
        c.emit('local k:4 = b & 31;')
        c.emit('local r:4 = (a >> k) | (a << (32 - k));')
        c.emit('if (k != 0) goto <ok>;')
        c.emit('r = a;')
        c.emit('<ok>')
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
    elif op == '<c>':
        c.emit('local k:4 = b;')
        c.emit('local w:8 = (zext((psr >> 1) & 1) << 32) | zext(a);')
        c.emit('local x:8 = (w >> k) | (w << (33 - k));')
        c.emit('local r:4 = x:4;')
        c.emit('%s = r;' % d)
        c.emit('local cb:4 = x(4);')
        c.emit('psr = (psr & 0xfffffffd) | ((cb & 1) << 1);')
        c.emit('setNZ(r);')
    elif op == '<<<':
        # signed saturating shift left
        c.emit('local w:8 = sext(a) << b;')
        c.emit('local r:4 = w:4;')
        c.emit('if (sext(r) == w) goto <ok>;')
        c.emit('r = 0x7fffffff;')
        c.emit('if (a s>= 0) goto <ok>;')
        c.emit('r = 0x80000000;')
        c.emit('<ok>')
        c.emit('%s = r;' % d)
        c.emit('setNZ(r);')
    else:
        raise Unsupported(op)
    return '', body(c)
